INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-k8s-1', 'wi-k8s-e1', 'p-001', 'Kicking off the control plane hardening initiative. We need 99.99% uptime on the API server. Let''s start with the HA design review.', FALSE, NOW() - INTERVAL '90 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-k8s-2', 'wi-k8s-e1', 'p-013', 'Are we capturing API call latencies during the failover? That data will be critical for our SLO model.', FALSE, NOW() - INTERVAL '88 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-k8s-3', 'wi-k8s-e1', 'p-001', 'Good point. I''ll add etcd latency histograms and leader election metrics to the telemetry plan.', FALSE, NOW() - INTERVAL '87 days') ON CONFLICT (id) DO NOTHING;

INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-k8s-4', 'wi-k8s-e2', 'p-002', 'Starting the networking overhaul. Cilium will give us better observability and native XDP support.', FALSE, NOW() - INTERVAL '85 days') ON CONFLICT (id) DO NOTHING;
