INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-k8s-8', 'wi-k8s-f1', 'p-004', 'Ran the failover simulation yesterday. cp1 → cp2 failover took 8 seconds. Well within our RTO budget.', FALSE, NOW() - INTERVAL '73 days') ON CONFLICT (id) DO NOTHING;

